import tiktoken

enc = tiktoken.encoding_for_model("{{model_name}}")

def chunk(text: str, size: int = {{chunk_tokens}}, overlap: int = {{overlap}}) -> list[str]:
    ids = enc.encode(text)
    out, start = [], 0
    while start < len(ids):
        end = min(start + size, len(ids))
        out.append(enc.decode(ids[start:end]))
        if end == len(ids):
            break
        start = end - overlap
    return out
